// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        // Bound amount to avoid overflow
        amount = bound(amount, 1, 1e18);
        // Ensure depositor is not the zero address
        vm.assume(depositor != address(0));

        // Fund depositor with enough ether
        vm.deal(depositor, amount);

        // Have depositor make a deposit
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Record contract balance before migration
        uint256 contractBalanceBefore = address(c).balance;

        // Create a target address for migration
        address target = address(0x1234);

        // Perform migration as the creator (msg.sender in setUp)
        c.migrateTo(target);

        // After migration, the entire contract balance should be transferred to target
        // In the correct version, target receives the balance; in the bug, msg.sender receives it
        assertTrue(address(c).balance == 0);
        assertTrue(target.balance == contractBalanceBefore);
    }
}

